<?php
declare(strict_types=1);
require_once __DIR__.'/ArtisticGeneratedAdoptionTest.php';
use DigiForge\AI\{ImageGenerationExecution,ImageGenerationJournal,ProviderEvidenceRepository,MonetaryReservationRepository,ShopAiGovernanceRepository};
final class ImageTaskReconciliationTest extends WP_UnitTestCase {
 use PhotoWorkflowFixtureIsolation {tearDown as private restoreFixture;}
 private array $floors=[];
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();ShopAccessFixture::reset();$this->capturePhotoFixtureState();global $wpdb;foreach(['jobs','ai_models','ai_tasks','integrations','integration_secrets','research_candidates','research_reviews','opportunities','product_families','products','product_versions']as $m){$t=DigiForge\Database\Tables::{$m}();$this->floors[$t]=(int)$wpdb->get_var('SELECT COALESCE(MAX(id),0) FROM '.$t);}wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['personalized_pod'],['manage_digiforge_pod','manage_digiforge_research','manage_digiforge_ai']);DigiForge\Core\Settings::protectProduction();$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');}
 protected function tearDown():void {global $wpdb;foreach(array_reverse($this->floors,true)as $t=>$id)$wpdb->query('DELETE FROM '.$t.' WHERE id>'.(int)$id);$this->restoreFixture();}
 private function checked($v):array {self::assertNotWPError($v,is_wp_error($v)?$v->get_error_code():'');return $v;}
 private function bound(bool $meter=true,?array $policy=null):array {
  $p=$policy??ImagePanelFixture::policy();$spec=ImagePanelFixture::specification();$s=new ImageGenerationExecution();$j=$this->checked($s->prepareDesign('personalized_pod',$spec['hash'],$p['hash'],['run_id'=>'image-bill-'.wp_generate_uuid4(),'started_at'=>gmdate('Y-m-d H:i:s')]));$money=new MonetaryReservationRepository();$this->checked($money->reviewQuote('personalized_pod',ImagePanelFixture::quote($j),'CONFIRM_PROVIDER_QUOTE'));$q=$this->checked($money->findQuote('personalized_pod',$j['identity']['wire_contract']));$u=$this->checked((new ShopAiGovernanceRepository())->reserveGeneration('personalized_pod','render','image-'.$j['id'],$j['identity']['run_context'],$q));$jr=new ImageGenerationJournal();$j=$this->checked($jr->append($j['id'],$j['event_sha256'],['state'=>'RESERVED','usage_id'=>(int)$u['id']]));$j=$this->checked($jr->append($j['id'],$j['event_sha256'],['state'=>'DISPATCHING']));$id='req_synthetic_bill_'.str_replace('-','',wp_generate_uuid4());$body=json_encode(['created'=>time(),'data'=>[['b64_json'=>'AA==']],'usage'=>['input_tokens'=>4,'output_tokens'=>3,'total_tokens'=>7,'input_tokens_details'=>['text_tokens'=>2,'image_tokens'=>2]]]);if($meter)$this->checked((new ProviderEvidenceRepository())->recordImageOutcome((int)$u['id'],'personalized_pod',$id,'gpt-image-1',$body,$j['identity']['wire_contract']['request_sha256'],'NETWORK'));$j=$this->checked($jr->append($j['id'],$j['event_sha256'],['state'=>'UNKNOWN','error_class'=>'SYNTHETIC_METERING_WITHOUT_VALID_ARTWORK']));$doc=['provider'=>'openai','invoice_id'=>'synthetic-'.wp_generate_uuid4(),'evidence_kind'=>'SYNTHETIC_TEST_ONLY','finality'=>['status'=>'FINAL','additional_charges_possible'=>false],'lines'=>[['line_id'=>'one','response_id'=>$id,'model'=>'gpt-image-1','currency'=>'USD','amount'=>'0.010000']]];return [$s,$j,$doc,$spec,$p];
 }
 private function reconcile(array $f,array $doc,?string $event=null):array|WP_Error {self::assertTrue(method_exists($f[0],'reconcile'),'Image tasks need exact-job original-statement review without retrying unknown generation.');return $f[0]->reconcile('personalized_pod',$f[1]['id'],$event??$f[1]['event_sha256'],json_encode($doc),true);}
 public function testUnknownImageChargeReconcilesIdempotentlyWithoutAdoptingOrRefunding():void {$f=$this->bound();$cost=$this->checked($this->reconcile($f,$f[2]));self::assertSame('0.010000',$cost['actual_charge']);self::assertFalse($cost['refund_assumed']);self::assertSame($cost,$this->checked($this->reconcile($f,$f[2])));self::assertSame('UNKNOWN',$this->checked($f[0]->read('personalized_pod',$f[1]['id']))['state']);self::assertWPError($f[0]->run('personalized_pod',$f[1]['id']));self::assertSame(10000,$this->checked((new MonetaryReservationRepository())->exposure('personalized_pod','USD',$f[1]['identity']['run_context']['run_id']))['run']);}
 public function testCancelledTaskRetainsUnknownHoldUntilExactMeteredZeroEvidence():void {$f=$this->bound();$cancel=$this->checked($f[0]->cancel('personalized_pod',$f[1]['id']));$doc=$f[2];$doc['lines'][0]['amount']='0.000000';self::assertWPError($this->reconcile($f,$doc));$cost=$this->checked($this->reconcile($f,$doc,$cancel['event_sha256']));self::assertSame('0.000000',$cost['actual_charge']);self::assertSame('CANCELLED',$this->checked($f[0]->read('personalized_pod',$f[1]['id']))['state']);self::assertFalse($cost['refund_assumed']);}
 public function testMissingMeterWrongRequestAndConflictingStatementCannotReleaseFunds():void {$f=$this->bound(false);self::assertWPError($this->reconcile($f,$f[2]));self::assertSame(20000,$this->checked((new MonetaryReservationRepository())->exposure('personalized_pod','USD',$f[1]['identity']['run_context']['run_id']))['run']);$f=$this->bound(true,$f[4]);$bad=$f[2];$bad['lines'][0]['response_id']='req_foreign';self::assertWPError($this->reconcile($f,$bad));$bad=$f[2];$bad['lines'][]=$bad['lines'][0];self::assertWPError($this->reconcile($f,$bad));$this->checked($this->reconcile($f,$f[2]));$bad=$f[2];$bad['lines'][0]['amount']='0.000000';self::assertWPError($this->reconcile($f,$bad));}
 public function testNoMeteredAttemptNoConfirmationForeignShopAndRevocationDeny():void {$f=$this->bound();self::assertTrue(method_exists($f[0],'reconcile'));self::assertWPError($f[0]->reconcile('digital',$f[1]['id'],$f[1]['event_sha256'],json_encode($f[2]),true));self::assertWPError($f[0]->reconcile('personalized_pod',$f[1]['id'],$f[1]['event_sha256'],json_encode($f[2]),false));wp_get_current_user()->add_cap('manage_digiforge_ai',false);self::assertWPError($f[0]->reconcile('personalized_pod',$f[1]['id'],$f[1]['event_sha256'],json_encode($f[2]),true));}
 public function testProvisionalStatementCannotReleaseExposure():void {$f=$this->bound();foreach([null,['status'=>'PROVISIONAL','additional_charges_possible'=>false],['status'=>'FINAL','additional_charges_possible'=>true]] as $finality){$doc=$f[2];$doc['finality']=$finality;self::assertWPError($this->reconcile($f,$doc));}self::assertSame(20000,$this->checked((new MonetaryReservationRepository())->exposure('personalized_pod','USD',$f[1]['identity']['run_context']['run_id']))['run']);}
 public function testOperatorCanSeeExactChargeAndFinalStatementControl():void {$f=$this->bound();ob_start();(new DigiForge\Portal\ImageGenerationPanel())->render('personalized_pod',$f[3]['record']['commercial_hash'],$f[3]['hash']);$html=ob_get_clean();self::assertStringContainsString('design_image_statement',$html);self::assertStringContainsString('statement_file',$html);self::assertStringContainsString('Final statement',$html);self::assertStringContainsString($f[1]['event_sha256'],$html);}
 public function testOverCeilingChargeIsRetainedAndBlocksAdmission():void {$f=$this->bound();$doc=$f[2];$doc['lines'][0]['amount']='0.030000';self::assertWPError($this->reconcile($f,$doc));$snapshot=$this->checked((new ProviderEvidenceRepository())->snapshot($f[1]['usage_id'],'personalized_pod'));self::assertSame('RESERVATION_BOUND_EXCEEDED',$snapshot['cost_state']);self::assertWPError((new MonetaryReservationRepository())->exposure('personalized_pod','USD',$f[1]['identity']['run_context']['run_id']));}
 public function testCompetingGenerationLeaseCannotSettleOrReleaseHold():void {$f=$this->bound();global $wpdb;$other=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$name=DigiForge\AI\ImageGenerationHttpClient::lockName($f[1]['id']);try{self::assertSame('1',(string)$other->get_var($other->prepare('SELECT GET_LOCK(%s,0)',$name)));$result=$this->reconcile($f,$f[2]);self::assertWPError($result);self::assertSame('image_execution_busy',$result->get_error_code());}finally{$other->get_var($other->prepare('SELECT RELEASE_LOCK(%s)',$name));$other->close();}self::assertSame(20000,$this->checked((new MonetaryReservationRepository())->exposure('personalized_pod','USD',$f[1]['identity']['run_context']['run_id']))['run']);}
 public function testPermissionWithdrawalAtOwnedLockReleaseDeniesResponseWithoutErasingCharge():void {$f=$this->bound();$name=DigiForge\AI\ImageGenerationHttpClient::lockName($f[1]['id']);$revoked=false;$q=static function($sql)use($name,&$revoked){if(str_contains($sql,'RELEASE_LOCK')&&str_contains($sql,$name)){$revoked=true;wp_get_current_user()->add_cap('manage_digiforge_ai',false);}return $sql;};add_filter('query',$q);try{self::assertWPError($this->reconcile($f,$f[2]));self::assertTrue($revoked);}finally{remove_filter('query',$q);wp_get_current_user()->add_cap('manage_digiforge_ai',true);}self::assertSame('0.010000',$this->checked((new ProviderEvidenceRepository())->snapshot($f[1]['usage_id'],'personalized_pod'))['settlement']['charge']['amount']);}
 public function testLegacyChargeDoesNotBecomeVerifiedFinalityByReadingIt():void {$f=$this->bound();$doc=$f[2];unset($doc['finality']);$bytes=json_encode($doc);$e=['source'=>'provider_statement','source_sha256'=>hash('sha256',$bytes),'source_document'=>$bytes,'invoice_id'=>$doc['invoice_id']]+$doc['lines'][0];$this->checked((new ProviderEvidenceRepository())->settle($f[1]['usage_id'],'personalized_pod',$e));$cost=$this->checked($f[0]->costEvidence('personalized_pod',$f[1]['id']));self::assertSame('UNVERIFIED_LEGACY_STATEMENT',$cost['charge_finality']??null);self::assertFalse($cost['refund_assumed']);self::assertWPError($this->reconcile($f,$f[2]),'A changed finality assertion cannot rewrite immutable old settlement bytes.');}
 public function testStaleArtworkCannotHideAuthenticatedFinancialQueue():void {$f=$this->bound();global $wpdb;$prefix=(new ReflectionClass(DigiForge\Research\DesignFactoryRepository::class))->getConstant('PREFIX');self::assertSame(1,$wpdb->delete($wpdb->options,['option_name'=>$prefix.'version_'.$f[3]['hash']]));self::assertWPError((new DigiForge\Research\DesignFactoryRepository())->read('personalized_pod',$f[3]['hash']));ob_start();(new DigiForge\Portal\CommercialResearchPanel())->render('personalized_pod');$html=ob_get_clean();self::assertStringContainsString('image_charge_reconcile',$html);self::assertStringContainsString($f[1]['id'],$html);self::assertWPError($f[0]->artifact('personalized_pod',$f[1]['id']));self::assertSame('UNKNOWN',$this->checked((new ImageGenerationJournal())->read($f[1]['id']))['state']);}
 public function testChargeDiscoveryRechecksAuthorityBeforeReturningAnyJob():void {$f=$this->bound();$jr=new ImageGenerationJournal();self::assertTrue(method_exists($jr,'forReconciliation'));$revoked=false;$q=static function($sql)use(&$revoked){if(!$revoked&&str_starts_with(ltrim($sql),'SELECT option_value')&&str_contains($sql,'JSON_EXTRACT')&&str_contains($sql,'image')){$revoked=true;wp_get_current_user()->add_cap('manage_digiforge_ai',false);}return $sql;};add_filter('query',$q);try{self::assertWPError($jr->forReconciliation());self::assertTrue($revoked);}finally{remove_filter('query',$q);wp_get_current_user()->add_cap('manage_digiforge_ai',true);}}
 public function testBillingDiscoveryCannotEmitRowsAfterResearchRevocation():void {$f=$this->bound();$revoked=false;$q=static function($sql)use(&$revoked){if(!$revoked&&str_starts_with(ltrim($sql),'SELECT option_value')&&str_contains($sql,'JSON_EXTRACT')&&str_contains($sql,'image')){$revoked=true;wp_get_current_user()->add_cap('manage_digiforge_research',false);}return $sql;};add_filter('query',$q);try{ob_start();(new DigiForge\Portal\ImageGenerationPanel())->renderReconciliation('personalized_pod');$html=ob_get_clean();self::assertTrue($revoked);self::assertStringNotContainsString($f[1]['id'],$html);self::assertStringNotContainsString('image_charge_reconcile',$html);}finally{remove_filter('query',$q);wp_get_current_user()->add_cap('manage_digiforge_research',true);}}
 public function testForeignCreatorCannotDiscoverOrReconcileThisJob():void {$f=$this->bound();$actor=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($actor);ShopAccessFixture::authorizeActor($actor,['personalized_pod'],['manage_digiforge_pod','manage_digiforge_research','manage_digiforge_ai']);global $wpdb;self::assertNotFalse($wpdb->query('COMMIT'));self::assertNotFalse($wpdb->query('SET autocommit=1'));self::assertSame([],$this->checked((new ImageGenerationJournal())->forReconciliation()));self::assertWPError($f[0]->costEvidence('personalized_pod',$f[1]['id']));self::assertWPError($this->reconcile($f,$f[2]));}
 public function testCorruptOwnedJournalCannotBecomeFinancialAuthority():void {$f=$this->bound();global $wpdb;self::assertSame(1,$wpdb->update($wpdb->options,['option_value'=>'{}'],['option_name'=>'digiforge_image_job_head_'.$f[1]['id']]));self::assertWPError((new ImageGenerationJournal())->forReconciliation());self::assertWPError($f[0]->costEvidence('personalized_pod',$f[1]['id']));}
 public function testSimulationCannotBecomeBillOrZeroCharge():void {$p=ImagePanelFixture::policy();$spec=ImagePanelFixture::specification();$j=ImagePanelFixture::candidate($spec,$p);$s=new ImageGenerationExecution();self::assertTrue(method_exists($s,'costEvidence'));$cost=$this->checked($s->costEvidence('personalized_pod',$j['id']));self::assertNull($cost['actual_charge']);self::assertWPError($s->reconcile('personalized_pod',$j['id'],$j['event_sha256'],'{"provider":"openai"}',true));}
}
